export const meta = {
  name: 'v1.1-tech-debt-sweep',
  description: 'Exhaustively sweep all v1.1 phase artifacts + milestone audit + code TODOs for tech debt and deferred items, then dedupe into a tracked TODO list',
  phases: [
    { title: 'Sweep', detail: 'parallel agents comb phase groups + audit + code TODOs' },
    { title: 'Synthesize', detail: 'dedupe, categorize, assign IDs, emit markdown checkbox todos' },
  ],
}

const BASE = '/Users/myankelev/Code/random/cipher-box/.planning/phases'

const ITEM_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          phase: { type: 'string', description: 'phase number e.g. "23" or "19.1"' },
          title: { type: 'string', description: 'short imperative title of the debt/deferred item' },
          detail: { type: 'string', description: 'one-sentence specifics incl. file path or symbol if known' },
          category: { type: 'string', enum: ['code-debt', 'deferred-feature', 'human-verification', 'test-coverage', 'process-gap', 'known-limitation'] },
          severity: { type: 'string', enum: ['high', 'medium', 'low', 'info'] },
          source: { type: 'string', description: 'origin file/section e.g. "23-VERIFICATION.md deferred" or "audit frontmatter"' },
        },
        required: ['phase', 'title', 'detail', 'category', 'severity', 'source'],
      },
    },
  },
  required: ['items'],
}

const GROUPS = [
  { label: '18-23', phases: ['18-performance-instrumentation', '19-ipns-resolution-improvement', '19.1-extract-core-crypto-sdk-as-shared-package', '19.2-ipfs-upload-performance-optimization', '20-vault-migration', '21-byo-ipfs-node-support', '22-performance-baselines-completion', '23-rust-sdk-extraction'] },
  { label: '24-31', phases: ['24-bug-fixes-test-infrastructure', '25-desktop-enhancements', '26-observability-ux-tuning', '27-writable-shares-poc', '28-code-hygiene-logging', '29-infrastructure-hardening', '30-web-app-observability', '31-structural-decomposition'] },
  { label: '32-39', phases: ['32-fuse-async-filepointer-resolution', '33-windows-async-filepointer-resolution', '34-e2e-test-expansion-staging-baselines', '35-phala-testnet-tee-migration', '36-inline-upload-progress', '37-parallel-batch-upload-pipeline', '38-retire-deprecated-web-services', '39-user-configurable-vault-parameters'] },
  { label: '40-49', phases: ['40-desktop-vault-settings-integration', '41-package-and-app-versioning-and-release-cycles', '42-api-unpin-integrity', '43-fuse-write-durability', '44-ipns-conflict-handling', '45-desktop-fuse-write-durability-cleanup', '46-desktop-fuse-data-loss-bugs-replay-hardening', '47-sdk-folder-state-publish-consolidation', '48-sdk-self-bootstrap-regression-fix-and-shared-folder-metadata', '49-shared-folder-move-intra-share-and-usefoldernavigation-unwra'] },
]

phase('Sweep')

const groupThunks = GROUPS.map((g) => () =>
  agent(
    `You are sweeping completed GSD phase artifacts for EVERY piece of tech debt, deferred item, known limitation, accepted deviation, human-verification item, missing test coverage, and TODO.

Read these phase directories under \`${BASE}/\`:
${g.phases.map((p) => '- ' + p).join('\n')}

For each phase, read (if present): \`{N}-VERIFICATION.md\` (look at gaps, deferred, anti-patterns, human-needed/UAT items, "accepted deviation" notes), \`{N}-CONTEXT.md\` (the \`<deferred>\` section AND any decision noted as a tradeoff/limitation), and all \`{N}-NN-SUMMARY.md\` files (the \`deferred\`/\`tech_debt\` frontmatter and any "deferred to" prose). Do NOT read PLAN.md or RESEARCH.md.

Extract a structured item for EVERY distinct deferred/debt/limitation/human-verification/missing-test item you find. Be exhaustive and literal — if a SUMMARY lists 4 deferred bullets, that's 4 items. Include file paths/symbols in \`detail\` when the artifact gives them. Assign severity by your judgment: high = correctness/data-loss/security risk; medium = meaningful functional gap or maintainability risk; low = minor/cosmetic; info = informational/operational note. Use category: code-debt (in-code shortcut/TODO/accepted deviation), deferred-feature (functionality intentionally postponed), human-verification (UAT/live-service confirmation pending), test-coverage (missing tests), process-gap (missing verification doc / Nyquist gap), known-limitation (documented behavioral limitation). Return ONLY the structured object.`,
    { label: `sweep:${g.label}`, phase: 'Sweep', schema: ITEM_SCHEMA },
  ),
)

const auditThunk = () =>
  agent(
    `Read \`/Users/myankelev/Code/random/cipher-box/.planning/v1.1-MILESTONE-AUDIT.md\`. Its YAML frontmatter contains a \`tech_debt:\` block (per-phase items), a \`gaps:\` block (orphaned requirements + phases missing VERIFICATION.md), and a \`nyquist:\` block (partial/missing phases). Extract EVERY item from all three blocks as structured items. For orphaned requirements (PERF-01..04) and missing-VERIFICATION phases, note in detail whether the body text says they were since closed/resolved. Use category process-gap for verification/nyquist gaps, and the most fitting category for the tech_debt entries. source = "audit frontmatter". Return ONLY the structured object.`,
    { label: 'sweep:audit', phase: 'Sweep', schema: ITEM_SCHEMA },
  )

const codeTodoThunk = () =>
  agent(
    `Find notable in-code TODO/FIXME/XXX/HACK markers tied to v1.1 milestone work. Run ripgrep scoped to the SDK and app source — for example:
\`rg -n --no-heading -e 'TODO|FIXME|XXX|HACK' /Users/myankelev/Code/random/cipher-box/crates /Users/myankelev/Code/random/cipher-box/packages /Users/myankelev/Code/random/cipher-box/apps -g '!*test*' -g '!*node_modules*' -g '!*/dist/*' -g '!*/target/*'\`
Then read enough surrounding context for each hit to write a meaningful item. EXCLUDE generated files, vendored code, and trivial/boilerplate TODOs. Focus on markers that represent real deferred engineering work (e.g. the audit flagged \`crates/fuse/src/platform/windows/write_ops.rs\` mkdir publish retry). Cap at the ~20 most significant. category = code-debt unless clearly otherwise; source = "code TODO: <file>:<line>". detail must include the file:line and what the TODO says. Return ONLY the structured object.`,
    { label: 'sweep:code-todos', phase: 'Sweep', schema: ITEM_SCHEMA },
  )

const swept = await parallel([...groupThunks, auditThunk, codeTodoThunk])
const raw = swept.filter(Boolean).flatMap((r) => (r && r.items) || [])
log(`swept ${raw.length} raw tech-debt items from ${swept.filter(Boolean).length} agents`)

phase('Synthesize')

const FINAL_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    summary: { type: 'string', description: 'one-line count summary e.g. "28 tracked items: 4 high, 11 medium, ..."' },
    groups: {
      type: 'array',
      description: 'items organized into thematic groups',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          theme: { type: 'string', description: 'theme name e.g. "FUSE / Desktop durability", "SDK / Web architecture", "BYO-IPFS", "Observability & process"' },
          items: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                id: { type: 'string', description: 'stable kebab-case id e.g. "td-byo-unpin-wire"' },
                phase: { type: 'string' },
                title: { type: 'string' },
                detail: { type: 'string' },
                category: { type: 'string', enum: ['code-debt', 'deferred-feature', 'human-verification', 'test-coverage', 'process-gap', 'known-limitation'] },
                severity: { type: 'string', enum: ['high', 'medium', 'low', 'info'] },
                source: { type: 'string' },
                status: { type: 'string', enum: ['open', 'likely-resolved'], description: 'likely-resolved only if an artifact explicitly says it was since closed' },
              },
              required: ['id', 'phase', 'title', 'detail', 'category', 'severity', 'source', 'status'],
            },
          },
        },
        required: ['theme', 'items'],
      },
    },
  },
  required: ['summary', 'groups'],
}

const synth = await agent(
  `You are consolidating raw tech-debt items swept from CipherBox v1.1 milestone artifacts into a clean, deduplicated, tracked TODO list.

Here are the raw items (JSON):
${JSON.stringify(raw)}

Tasks:
1. DEDUPE — merge items that describe the same underlying debt (e.g. the Rust FUSE 409-merge parity limitation appears in both phase 43 and 44; the BYO provider.unpin wiring; the Windows mkdir publish-retry TODO which appears in both the audit and a code TODO). When merging, keep the richest detail and cite all phases involved.
2. Mark status "likely-resolved" ONLY when an artifact explicitly states the item was since closed (e.g. PERF-01..04 orphans and missing-VERIFICATION phases that the audit body or later ledger close-out resolved, Phase 30 logger transport "deferred until Phase 28 ships" which has since shipped). Everything else is "open".
3. Assign a stable kebab-case \`id\` to each item (prefix \`td-\`).
4. Organize into 5-8 thematic groups (e.g. FUSE/Desktop durability, SDK/Web architecture, BYO-IPFS, Sharing, Observability/process, Release/ops, Deferred-to-v1.2). Order groups by aggregate severity (most severe first); within a group order by severity (high→info).
5. Preserve EVERY distinct item — do not drop anything except true duplicates. Be exhaustive.

Return ONLY the structured object.`,
  { label: 'synthesize', phase: 'Synthesize', schema: FINAL_SCHEMA, effort: 'high' },
)

return synth

