for f in sorted(glob.glob(os.path.join(wf, "agent-*.jsonl"))):
    if synth in f:
        continue
    last_items = None
    with open(f) as fh:
        for line in fh:
            line=line.strip()
            if not line: continue
            try:
                ev = json.loads(line)
            except Exception:
                continue
            msg = ev.get("message") or {}
            content = msg.get("content")
            if not isinstance(content, list): continue
            for block in content:
                if isinstance(block, dict) and block.get("type")=="tool_use":
                    inp = block.get("input") or {}
                    if isinstance(inp, dict) and isinstance(inp.get("items"), list):
                        last_items = inp["items"]
    if last_items is not None:
        out.append({"agent": os.path.basename(f), "count": len(last_items), "items": last_items})

total = sum(o["count"] for o in out)
print(f"agents_with_items={len(out)} total_items={total}")
for o in out:
    print(f"  {o['agent']}: {o['count']} items")
with open("/tmp/v11_techdebt_raw.json","w") as w:
    json.dump([it for o in out for it in o["items"]], w, indent=1)
print("wrote /tmp/v11_techdebt_raw.json")
